fn witchbane_orb_card_data() {
    let reg = registry();
    let id = reg.get_id_by_name("Witchbane Orb").unwrap();
    let data = reg.card_data(id).unwrap();
    assert!(data.card_types.contains(&CardType::Artifact));
    assert_eq!(data.cost.as_ref().unwrap().mana_value(), 4);
}

